import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
m = int(data[1])
a = list(map(int, data[2:2+n]))
edges = [(int(data[2+n+2*i]), int(data[2+n+2*i+1])) for i in range(n-1)]
queries = [(data[2+n+2*(n-1)+2*i], int(data[2+n+2*(n-1)+2*i+1])) for i in range(m)]

# Build the tree
from collections import defaultdict, deque

tree = defaultdict(list)
for v, u in edges:
    tree[v].append(u)
    tree[u].append(v)

# Initialize values and lazy propagation arrays
values = a[:]
lazy = [0] * (n + 1)

# Function to apply lazy propagation
def apply_lazy(node, val):
    values[node] += val
    lazy[node] += val

# Function to push lazy propagation down to children
def push_down(node):
    for child in tree[node]:
        if lazy[node] != 0:
            apply_lazy(child, -lazy[node])
    lazy[node] = 0

# Process queries
def process_query(query_type, node, val=None):
    if query_type == '1':
